e,false,false,"1",1,4117,5000,2140,4150,5333,8433,7333,8133,11967,8133,3000,"fuji_cj"},h)g[403901]=b({e[46057],403901,false,109,221,false,200039,false,"deco/character/qixi",302002,60,1,false,false,false,171,"1",false,false,false,false,false,false,false,"30,-160,1.1","0,60,1","60,30,1",false,false,false,"0,80,1","40,80,1",false,false,false,1778,989,409,1437,828,1312,1958,1437,828,1312,1126,"qixi"},h)g[403902]=b({e[13034],403902,1,4,222,"「毎日毎日、ババアのお使いばっかだし、たまにはこうしてサボらねーとな。\nどうだ、オレ様の赤い糸、綺麗だろ？\nふふん、一本だけなら分けてやってもいいぜ？」",200039,1,"deco/character/qixi_0",302002,60,1,1,1767,973,423,1110,493,2229,2504,1110,684,2229,1261,false,false,false,false,false,false,false,false,false,false,false,false,"qixi_0"},h)g[403903]=b({e[21034],403903,2,38,223,"「チェ、見る目ねぇなぁ……。この砂の城、オレ様が何時間かけて作ったと思ってんだ？　そこらのヤツとは違ぇんだよ。んなことより、いたずらで壊されたら困るからちゃんと警戒しねぇとな！　お前も暇なら手伝ってくれ。」",200039,2,"deco/character/qixi_YZ",false,false,false,false,false,false,false,false,false,false,false,"0,-180,1",1827,978,380,878,460,2424,2605,878,667,2424,1261,false,false,false,false,false,false,false,false,false,false,false,false,"qixi_xr"},h)g[403904]=b({e[23034],403904,14,33,224,"「近接戦闘が出来ないから、アーチャーは弱い？　誰がそんなでたらめ言ったんだ。オレ様の弓さばき、近づける敵なんていやしねーぞ！」",200039,2,"deco/character/qixi_YSJ",false,false,false,false,false,false,false,false,false,"0,120,1.01","-110,110,1.01","0,60,1.01","-220,100,1.01","-220,180,1.01",2101,1073,380,674,false,2713,3324,674,762,2713,1261,false,false,false,false,false,false,false,false,false,false,false,false,"qixi_ysj"},h)g[403905]=b({e[17057],403905,4,97,225,"「勘違いすんなよ、たまたまここで仕事してただけだ！ 誰がお前なんかのこと待つってんだ……\nま、来たからには、勝手にどっか行くんじゃねぇぞ。この後、クリスマスのベルが鳴る頃に、下の広場で花火が上がんだ。\nオレ様には……じゃなくて、オレ様の『人類恋愛攻略ガイド』には、まだ聖夜のパターンが欠けてんだよな～。」",200039,2,"deco/character/qixi_sd",false,false,false,false,false,false,false,"","qixi_sd"},h)g[404001]=b({e[25034],404001,false,110,226,false,200040,false,"deco/character/shecan",302002,60,false,false,false,false,-69,"1",false,false,false,false,false,false,false,"160,90,1",1754,858,405,1188,681,1638,2712,1188